const item = $input.first().json;
const payload = item.body ? item.body : item;

const confidence = (payload.triage && payload.triage.fused_confidence) ? payload.triage.fused_confidence : 0.90;
const location = payload.location || { sector: '(14, 22)', simulated_lat: 12.9716, simulated_lon: 77.5946 };
const victimName = (payload.triage && payload.triage.victim_name) ? payload.triage.victim_name : 'SURVIVOR';
const readings = payload.sensor_corroboration || {};

// Calculate Triage Tier & ETA
let priority = 'CODE RED (CRITICAL)';
let etaMinutes = 4.5;
if (confidence >= 0.85) {
  priority = 'CODE RED (IMMEDIATE EXTRACTION)';
  etaMinutes = 3.8;
} else if (confidence >= 0.70) {
  priority = 'CODE YELLOW (STABILIZE & SECURE)';
  etaMinutes = 6.2;
} else {
  priority = 'CODE GREEN (MONITOR)';
  etaMinutes = 10.0;
}

return [{
  json: {
    status: 'PARAMEDIC_DISPATCHED',
    incident_id: payload.incident_id || `SAR-${Date.now()}`,
    assigned_unit: 'MOBILE_RESCUE_ALPHA_01',
    eta_minutes: etaMinutes,
    triage_tier: priority,
    alert_dispatched: true,
    coordinates: location
  }
}];
